{"content":"/**
 * Guard JS - View Blocker for Unauthenticated Users
 * This script must be placed in the <head> of protected pages.
 * It checks for a valid token and redirects to login if the user is unauthenticated.
 */
(async function() {
    const API_BASE_URL = 'http://127.0.0.1:8080/api';

    // 1. Check for authentication token locally
    const token = localStorage.getItem('authToken');

    if (!token) {
        window.location.replace('login.html');
        return;
    }

    // 2. verify token validity with the backend
    try {
        const response = await fetch(`${API_BASE_URL}/auth/validate`, {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
            }
        });

        if (!response.ok) {
            throw new Error('Token validation failed');
        }

    } catch (error) {
        console.warn('Session expired or invalid:', error);
        localStorage.removeItem('authToken');
        window.location.replace('login.html');
    }
})();
